const listActiveRuns = `-- name: ListActiveRuns :many
SELECT id, task_id, parent_run_id, role, model, container_id, dsh_session_id, state, checkpoint, started_at, ended_at, tokens_in, tokens_out, cost_usd, created_at, version, updated_at, next_event_seq, token_hash, last_heartbeat_at, attempt, exit_code, prompt_version FROM run WHERE state IN ('PENDING', 'STARTING', 'RUNNING') ORDER BY created_at
`

// The reconciler's (P8) and the supervisor's own startup reap's view of
// "what should currently have a live container."
func (q *Queries) ListActiveRuns(ctx context.Context) ([]Run, error) {
	rows, err := q.db.Query(ctx, listActiveRuns)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Run
	for rows.Next() {
		var i Run
		if err := rows.Scan(
			&i.ID,
			&i.TaskID,
			&i.ParentRunID,
			&i.Role,
			&i.Model,
			&i.ContainerID,
			&i.DshSessionID,
			&i.State,
			&i.Checkpoint,
			&i.StartedAt,
			&i.EndedAt,
			&i.TokensIn,
			&i.TokensOut,
			&i.CostUsd,
			&i.CreatedAt,
			&i.Version,
			&i.UpdatedAt,
			&i.NextEventSeq,
			&i.TokenHash,
			&i.LastHeartbeatAt,
			&i.Attempt,
			&i.ExitCode,
			&i.PromptVersion,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

